import { electricityModule2Distractors } from "./electricityModule2Distractors.js";

export const electricityModule2Path = "/study/electricity/module-2";
export const electricityModule2Sources = {
  battery: { title: "E1.04 AMEM10001 Batteries", slides: 70 },
  induction: { title: "E1.05 Electromagnetic Induction", slides: 62, splitAt: 42 },
  generator: { title: "E1.06 DC Generators & Controls", slides: 79, splitAt: 56 },
};
export const electricityModule2Choice = [], electricityModule2Recall = [];
const topics = new Map();
function add(id, topic, deck, slides, prompt, options, why, recall) {
  if (electricityModule2Distractors[id]) options = [options[0], ...electricityModule2Distractors[id]];
  const citation = `${electricityModule2Sources[deck].title}, slide${slides.length > 1 ? "s" : ""} ${slides.join(", ")}`;
  const explanation = `${why} (${citation}.)`;
  const source = { deck, slides };
  electricityModule2Choice.push({ id: `electricity2-choice-${id}`, learningTarget: id, topic, prompt, options, correctIndex: 0, explanation, source });
  electricityModule2Recall.push({ id: `electricity2-word-${id}`, learningTarget: id, topic, prompt: recall[0], answer: recall[1], acceptedAnswers: [recall[1], ...(recall[2] ?? [])], explanation, source });
  if (!topics.has(topic)) topics.set(topic, []);
  topics.get(topic).push([options[0], `${why} (${citation}.)`]);
}

add("battery-energy", "cells", "battery", [3, 4], "What energy conversion takes place when a battery supplies a circuit?", ["Chemical energy to electrical energy", "Electrical energy to chemical energy during discharge", "Mechanical energy to electrical energy", "Electrical energy to mechanical energy"], "A discharging battery uses its chemical reaction to supply electrical energy to the external circuit. Recharging a secondary battery drives the reversible chemical process in the opposite direction.", ["A battery supplying a circuit converts _____ energy into electrical energy.", "chemical"]);
