function parts(bank, difficulty, kind, start) {
  const count = Math.ceil(bank.length / 36), size = Math.floor(bank.length / count), extra = bank.length % count;
  let offset = 0;
  return Array.from({ length: count }, (_, i) => {
    const questions = bank.slice(offset, offset + size + Number(i < extra)); offset += questions.length;
    const path = `${electricityModule2Path}/${kind === "typed" ? "one-word" : "practice"}-${start + i}`;
    return { slug: `electricity-module2-${difficulty}-${i + 1}`, course: "Electricity", courseSlug: "electricity", basePath: electricityModule2Path, path, storageId: path, questions, kind, difficulty, number: i + 1, title: `${difficulty === "easy" ? "Quiz Review" : difficulty === "medium" ? "Lecture Practice" : "One-Word Recall"} · Part ${i + 1}` };
  });
}
